var sites=world.Map.Sites.Select(s=>new{s.Id,position=new[]{s.Position.x,s.Position.y,s.Position.z},clearance=clearance(s.Position),groundDelta=s.Position.y-terrain.SampleHeight(s.Position)-terrain.transform.position.y}).ToArray();foreach(var s in sites)if(s.clearance<6||s.groundDelta<0||s.groundDelta>.6f)errors.Add("Recovery "+s.Id);
