foreach(var road in roads){var vs=road.sharedMesh.vertices;for(int i=0;i<vs.Length-2;i+=2){var a=(vs[i]+vs[i+1])*.5f;var b=(vs[i+2]+vs[i+3])*.5f;if(Physics.Raycast(a+Vector3.up*8,Vector3.down,out var supportA,20,1<<8,QueryTriggerInteraction.Ignore))a.y=supportA.point.y;else supportMissing++;
