var dir=(b-a).normalized;var side=Vector3.Cross(Vector3.up,dir);float w=Vector3.Distance(vs[i],vs[i+1])*.5f;float grade=Mathf.Atan2(Mathf.Abs(b.y-a.y),new Vector2(b.x-a.x,b.z-a.z).magnitude)*Mathf.Rad2Deg;maxRoadGrade=Mathf.Max(maxRoadGrade,grade);if(grade>24)slopes.Add(new { road=road.name,p=new[]{a.x,a.y,a.z},end=new[]{b.x,b.y,b.z},grade });foreach(float offset in new[]{-w*.45f,0,w*.45f}){var p=a+side*offset;roadSamples++;if(Physics.Raycast(p+Vector3.up*5,Vector3.down,out var support,12,1<<8,QueryTriggerInteraction.Ignore))p.y=support.point.y;else supportMissing++;if(terrain.SampleHeight(p)+terrain.transform.position.y>p.y+.35f){buriedRoads++;buriedSamples.Add(new{road=road.name,p=new[]{p.x,p.y,p.z},ground=terrain.SampleHeight(p)+terrain.transform.position.y});}var hits=Physics.OverlapBox(p+Vector3.up*1.45f,new Vector3(1.1f,.6f,2.1f),Quaternion.LookRotation(dir),1<<8,QueryTriggerInteraction.Ignore).Where(c=>!(c is TerrainCollider)&&!c.name.StartsWith("Road-")&&!c.name.Contains("Living Mud")&&!c.name.StartsWith("Broken Vector")&&!c.name.Contains("Bridge drive")&&!c.name.Contains("Bridge entry ramp")).ToArray();foreach(var hit in hits)obstacles.Add(new{road=road.name,collider=hit.name,p=new[]{p.x,p.y,p.z}});}}}
var water=env.GetComponentsInChildren<MeshFilter>().Single(f=>f.name=="River - continuous channel and cascade");var v=water.sharedMesh.vertices;float last=10000;int dry=0,uphill=0;var centers=new System.Collections.Generic.List<Vector3>();int centerCount=((System.Collections.ICollection)author.GetMethod("RiverPlan",flags).Invoke(null,null)).Count;for(int i=0;i<centerCount*2;i+=2){var p=(v[i]+v[i+1])*.5f;centers.Add(p);if(terrain.SampleHeight(p)+terrain.transform.position.y>p.y-.2f)dry++;if(p.y>last+.01f)uphill++;last=p.y;}
var bridgeResults=new System.Collections.Generic.List<object>();
foreach(var group in env.GetComponentsInChildren<Transform>().Where(t=>t.name.StartsWith("Bridge - surveyed"))){var deck=group.Find("Bridge drive surface");var p=deck.position;var closest=centers.OrderBy(q=>new Vector2(q.x-p.x,q.z-p.z).sqrMagnitude).First();float horizontal=new Vector2(closest.x-p.x,closest.z-p.z).magnitude;float waterClear=p.y-closest.y;float maxEndGap=0;foreach(var ramp in group.Cast<Transform>().Where(t=>t.name=="Bridge entry ramp")){var end=ramp.position+ramp.forward*(ramp.localScale.z*.5f)+Vector3.up*.085f;maxEndGap=Mathf.Max(maxEndGap,Mathf.Abs(end.y-terrain.SampleHeight(end)-terrain.transform.position.y));}bridgeResults.Add(new{name=group.name,horizontal,waterClear,maxEndGap});if(horizontal>1.6f||waterClear<1.2f||maxEndGap>.6f)errors.Add(group.name);}
int riverTrees=env.GetComponentsInChildren<CapsuleCollider>().Count(c=>c.name.Contains("P_")&&(float)author.GetMethod("RiverDistance",flags).Invoke(null,new object[]{c.bounds.center})<6+c.bounds.extents.x);
