var serializedMap=new UnityEditor.SerializedObject(world.Map);var checkpointData=serializedMap.FindProperty("roadCheckpoints");int resetErrors=0;for(int i=0;i<checkpointData.arraySize;i++){var p=checkpointData.GetArrayElementAtIndex(i).vector3Value;if(!Physics.Raycast(p+Vector3.up,Vector3.down,out var hit,3,1<<8,QueryTriggerInteraction.Ignore)||Mathf.Abs(p.y-hit.point.y-.14f)>.05f)resetErrors++;}
if(resetErrors>0)errors.Add("Unsupported reset points");if(maxRoadGrade>24)errors.Add("Road grade above 24 degrees");if(supportMissing>0||obstacles.Count>0)errors.Add("Drive corridor blocked");
System.IO.File.WriteAllText("/private/tmp/mountain-slopes.json",Newtonsoft.Json.JsonConvert.SerializeObject(slopes,Newtonsoft.Json.Formatting.Indented));var report=new{resetPoints=checkpointData.arraySize,resetErrors,scene=scene.path,playMode=false,buildStarted=false,sites,signs,roads=roads.Length,roadSamples,supportMissing,inactiveLegacyDriveMeshes=roads.Count(c=>!c.enabled),maxRoadGrade,obstacles,buriedRoads,buriedSamples,riverSamples=centers.Count,dryRiverSamples=dry,uphillRiverSamples=uphill,lakeConnection=last,bridges=bridgeResults,riverTrees,mountainRocks=env.Find("Mountain outcrops and scree").childCount,missingScripts=missing,shaderErrors,errors};System.IO.Directory.CreateDirectory("Docs/Validation/MountainApproaches");System.IO.File.WriteAllText("Docs/Validation/MountainApproaches/SceneChecks.json",Newtonsoft.Json.JsonConvert.SerializeObject(report,Newtonsoft.Json.Formatting.Indented));return new{roadSamples,supportMissing,maxRoadGrade,obstacles=obstacles.Count,buriedRoads,dry,uphill,riverTrees,report.mountainRocks,bridges=bridgeResults,errors,shaderErrors,missing};
